async function showSlide(index){if(screenShareActive)return;clearDrawCanvas();resetPan({silent:true});const token=++slideRenderToken;if(deckType==="pdf"&&pdfDoc){if(index<0||index>=totalPages)return;currentPage=index;safeText(E.slideNum,`${index+1} / ${totalPages}`);E.slideContent?.replaceChildren();const placeholder=document.createElement("div");placeholder.className="placeholder";placeholder.textContent="Rendering page...";E.slideContent?.appendChild(placeholder);appendDrawCanvas();try{const canvas=await renderPdfPage(index);if(token!==slideRenderToken||screenShareActive||currentPage!==index||deckType!=="pdf")return;if(canvas&&E.slideContent){E.slideContent.replaceChildren(canvas,E.drawCanvas);appendDrawCanvas();prefetchPdfNeighbors(index)}}catch(error){if(token===slideRenderToken)showError(`PDF render error: ${error.message}`)}}else if(deckType==="ppt"&&pptDoc){if(index<0||index>=totalPages)return;currentPage=index;safeText(E.slideNum,`${index+1} / ${totalPages}`);E.slideContent?.replaceChildren();const placeholder=document.createElement("div");placeholder.className="placeholder";placeholder.textContent="Rendering slide...";E.slideContent?.appendChild(placeholder);appendDrawCanvas();try{await renderPowerPointSlide(index,token)}catch(error){if(token===slideRenderToken)showError(`PowerPoint render error: ${error.message}`)}}else{if(index<0||index>=defaultSlides.length)return;defaultIndex=index;safeText(E.slideNum,`${index+1} / ${defaultSlides.length}`);renderDefaultSlide(index)}applyViewportTransform();updateDeckUI();markActivePageThumbnail(currentSlidePosition().index);invalidateHitCache();window.dispatchEvent(new CustomEvent("velosSlideChanged",{detail:{slideIndex:currentSlidePosition().index,totalSlides:currentSlidePosition().total,deckType}}))}

async function destroyCurrentDeckResources(nextType){if(nextType!=="pdf"&&pdfDoc){try{await pdfDoc.destroy?.()}catch(_){}pdfDoc=null;pdfCache.clear();pdfRenderPromises.clear()}if(nextType!=="ppt")pptDoc=null}
