async function renderPptThumbnail(index,host){if(!pptDoc?.slides?.[index]||!host.isConnected)return;const result=await renderPowerPointSvg(index,`velos-thumb-${index}-`);if(!host.isConnected||deckType!=="ppt")return;if(typeof result==="string")host.innerHTML=result;else if(result instanceof Element)host.replaceChildren(result);else host.innerHTML=String(result??"");const svg=host.querySelector("svg");if(svg){svg.removeAttribute("width");svg.removeAttribute("height");Object.assign(svg.style,{width:"100%",height:"100%"});svg.setAttribute("preserveAspectRatio","xMidYMid meet")}}
