function createPageThumbnail(index){const button=document.createElement("button");button.type="button";button.className="velos-page-thumb";button.dataset.slideIndex=String(index);button.setAttribute("aria-label",`Go to ${deckType==="pdf"?"page":"slide"} ${index+1}`);const preview=document.createElement("div");preview.className="velos-page-preview";const loading=document.createElement("span");loading.className="velos-thumb-loading";loading.textContent="Loading…";preview.appendChild(loading);const caption=document.createElement("div");caption.className="velos-page-caption";caption.textContent=`${deckType==="pdf"?"Page":"Slide"} ${index+1}`;button.append(preview,caption);button.addEventListener("click",()=>void showSlide(index));const render=async()=>{try{if(deckType==="pdf")await renderPdfThumbnail(index,preview);else if(deckType==="ppt")await renderPptThumbnail(index,preview);else renderDemoThumbnail(index,preview)}catch(error){preview.textContent="Preview unavailable";console.warn("Thumbnail render failed:",error)}};if("IntersectionObserver"in window&&deckType!=="demo"){thumbnailObserver??=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;thumbnailObserver?.unobserve(entry.target);const fn=entry.target.__velosRenderThumbnail;if(typeof fn==="function")void fn()}},{root:E.deckPagesList,rootMargin:"0px 250px"});preview.__velosRenderThumbnail=render;thumbnailObserver.observe(preview)}else void render();return button}
