function nextSlide(){if(screenShareActive){showToast("Live Screen mode · stop sharing before changing slides",900);return}const p=currentSlidePosition();void showSlide((p.index+1)%p.total)}
function prevSlide(){if(screenShareActive){showToast("Live Screen mode · stop sharing before changing slides",900);return}const p=currentSlidePosition();void showSlide((p.index-1+p.total)%p.total)}

function canPanViewport(){return currentZoom>CONFIG.pan.minZoom}
