function setPan(x,y,options={}){if(Number.isFinite(x))panX=x;if(Number.isFinite(y))panY=y;applyViewportTransform(options)}
function panBy(dx,dy,options={}){if(!canPanViewport())return false;setPan(panX+(Number.isFinite(dx)?dx:0),panY+(Number.isFinite(dy)?dy:0),options);return true}
function resetPan({silent=false}={}){panX=0;panY=0;applyViewportTransform({showIndicator:!silent})}
function applyZoom(scale,focalClientX=null,focalClientY=null){const nextZoom=clamp(Number(scale)||1,CONFIG.zoom.min,CONFIG.zoom.max),oldZoom=Math.max(.0001,currentZoom);if(Number.isFinite(focalClientX)&&Number.isFinite(focalClientY)&&Math.abs(nextZoom-oldZoom)>.00001&&stageCanvas){const rect=stageCanvas.getBoundingClientRect(),centerX=rect.left+rect.width/2,centerY=rect.top+rect.height/2,localX=(focalClientX-centerX-panX)/oldZoom,localY=(focalClientY-centerY-panY)/oldZoom;panX=focalClientX-centerX-localX*nextZoom;panY=focalClientY-centerY-localY*nextZoom}currentZoom=nextZoom;if(!canPanViewport()){panX=0;panY=0}applyViewportTransform({showIndicator:true})}
function resetZoom(){currentZoom=1;baseZoom=1;baseDist=0;zoomActive=false;zoomStableCount=0;panX=0;panY=0;applyViewportTransform({showIndicator:true})}
function isPointInsideSlideCard(x,y){const rect=E.slideCard?.getBoundingClientRect?.();return!!rect&&x>=rect.left&&x<=rect.right&&y>=rect.top&&y<=rect.bottom}

const INTERACTIVE_SELECTOR=["button","a[href]",'input:not([type="hidden"])',"select","textarea","label","summary",'[role="button"]','[role="link"]','[role="menuitem"]','[role="tab"]','[role="checkbox"]','[role="switch"]','[role="option"]','[tabindex]:not([tabindex="-1"])',"[onclick]","[data-action]","[data-clickable]"].join(",");
