function syncToolStates(){E.laserBtn?.classList.toggle("active",laserActive);E.highlightBtn?.classList.toggle("active",highlighterMode);E.mouseToggleBtn?.classList.toggle("active",mouseEnabled);E.mouseToggleBtn?.classList.toggle("mouse-on",mouseEnabled);E.autoBtn?.classList.toggle("active",autoPlay);E.laserToolBtn?.classList.toggle("active",laserActive);E.highlightToolBtn?.classList.toggle("active",highlighterMode);E.mouseToolBtn?.classList.toggle("active",mouseEnabled);E.mouseToolBtn?.classList.toggle("mouse-on",mouseEnabled);E.autoToolBtn?.classList.toggle("active",autoPlay);safeText(E.laserToolState,laserActive?"On":"Off");safeText(E.highlightToolState,highlighterMode?"On":"Off");safeText(E.mouseToolState,mouseEnabled?"On":"Off");safeText(E.autoToolState,autoPlay?"On":"Off");safeText(E.workspaceMode,mouseEnabled?"Air mouse":screenShareActive?"Live screen":highlighterMode?"Highlight":laserActive?"Laser":"Gesture");safeText(E.modeBadge,mouseEnabled?"Air mouse mode":screenShareActive?"Live screen mode":highlighterMode?"Highlight mode":laserActive?"Laser mode":gestureNavigationEnabled?"Gesture mode":"Manual mode")}

function openSettings(){E.settingsDrawer?.classList.add("show");E.backdrop?.classList.add("show")}
