function setAutoHidePanels(enabled){autoHidePanels=!!enabled;if(E.autoHideSwitch)E.autoHideSwitch.checked=autoHidePanels;if(E.drawerAutoHideSwitch)E.drawerAutoHideSwitch.checked=autoHidePanels}
